import{_ as e,H as a,f as n,i as t}from"./chunks/framework.BH2BK_3i.js";const c=JSON.parse('{"title":"05 | AutoGenAuto：所有测试工作即代码","description":"","frontmatter":{},"headers":[{"level":2,"title":"Auto Gen Auto 技术","slug":"auto-gen-auto-技术","link":"#auto-gen-auto-技术","children":[{"level":3,"title":"从何处下手","slug":"从何处下手","link":"#从何处下手","children":[]},{"level":3,"title":"如何实现","slug":"如何实现","link":"#如何实现","children":[]}]},{"level":2,"title":"测试等价类的规则","slug":"测试等价类的规则","link":"#测试等价类的规则","children":[]},{"level":2,"title":"业务的逻辑规则","slug":"业务的逻辑规则","link":"#业务的逻辑规则","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"牛刀小试","slug":"牛刀小试","link":"#牛刀小试","children":[]}],"relativePath":"自动化测试高手课/05｜AutoGenAuto：所有测试工作即代码.md","filePath":"自动化测试高手课/05｜AutoGenAuto：所有测试工作即代码.md","lastUpdated":1795563698000}'),p={name:"自动化测试高手课/05｜AutoGenAuto：所有测试工作即代码.md"};function i(l,s,o,r,h,u){return a(),n("div",null,[...s[0]||(s[0]=[t(`<h1 id="_05-autogenauto-所有测试工作即代码" tabindex="-1">05 | AutoGenAuto：所有测试工作即代码 <a class="header-anchor" href="#_05-autogenauto-所有测试工作即代码" aria-label="Permalink to &quot;05 | AutoGenAuto：所有测试工作即代码&quot;">​</a></h1><p>你好，我是柳胜。</p><p>我们前面用了 4 讲篇幅，讨论 ROI 模型和由此衍生出来的一套实践原则，从分层测试、选型思路和具体代码多个角度探索提升 ROI 的方法。</p><p>这些方法还都是基于常规的自动化测试开发流程，先有测试需求，再设计测试案例，然后做自动化。以登录测试为例，我画了一张流程图做说明。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E5%8A%A8%E5%8C%96%E6%B5%8B%E8%AF%95%E9%AB%98%E6%89%8B%E8%AF%BE/images/05/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E5%8A%A8%E5%8C%96%E6%B5%8B%E8%AF%95%E9%AB%98%E6%89%8B%E8%AF%BE/images/05/1.png" alt=""></a></p><p>自动化测试的开发成本，就是把测试需求转变成自动化测试代码这个过程花费的时间。在我们的图里，它是从左向右，所以我管它叫做水平开发成本。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E5%8A%A8%E5%8C%96%E6%B5%8B%E8%AF%95%E9%AB%98%E6%89%8B%E8%AF%BE/images/05/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E5%8A%A8%E5%8C%96%E6%B5%8B%E8%AF%95%E9%AB%98%E6%89%8B%E8%AF%BE/images/05/2.png" alt=""></a></p><p>当登录功能测试需求发生变化时，就会重新走一遍这个流程，出现了多个版本的测试需求，也会带来多个版本的自动化测试案例。从下图可见，这个版本是自上向下增加，所以我管它叫做垂直维护成本。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E5%8A%A8%E5%8C%96%E6%B5%8B%E8%AF%95%E9%AB%98%E6%89%8B%E8%AF%BE/images/05/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E5%8A%A8%E5%8C%96%E6%B5%8B%E8%AF%95%E9%AB%98%E6%89%8B%E8%AF%BE/images/05/3.png" alt=""></a></p><p>我们现在可以直观地看到开发成本和维护成本了。好，问题来了，有没有办法从流程上动手术，来降低这两个成本呢？</p><p>这就是我们今天要讲的 Automation Generate Automation，也叫自动化产生自动化测试代码，为了方便起见，下面的篇幅用缩写 Auto Gen Auto 来指代。</p><h2 id="auto-gen-auto-技术" tabindex="-1">Auto Gen Auto 技术 <a class="header-anchor" href="#auto-gen-auto-技术" aria-label="Permalink to &quot;Auto Gen Auto 技术&quot;">​</a></h2><p>常规的自动化测试，是指用代码实现设计好的 TestCase，而 Auto Gen Auto 的目的是让 TestCase 生成也自动化，如下图所示。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E5%8A%A8%E5%8C%96%E6%B5%8B%E8%AF%95%E9%AB%98%E6%89%8B%E8%AF%BE/images/05/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E5%8A%A8%E5%8C%96%E6%B5%8B%E8%AF%95%E9%AB%98%E6%89%8B%E8%AF%BE/images/05/4.png" alt=""></a></p><p>因为从测试需求到自动化测试案例是完全自动化的，每次需求改变的时候，只需运行一次Auto Gen Auto 即可生成新的自动化案例，垂直维护成本为零。所以 Auto Gen Auto 技术如果能落地，ROI 就会大大提高。</p><h3 id="从何处下手" tabindex="-1">从何处下手 <a class="header-anchor" href="#从何处下手" aria-label="Permalink to &quot;从何处下手&quot;">​</a></h3><p>那 Auto Gen Auto 用在哪性价比更高呢？</p><p>业界熟知的测试方法是黑盒测试和白盒测试。白盒测试从测试案例设计开始，需要我们先了解代码逻辑结果，一个函数里有几个判断分支，处理那些数据。基于这些了解，再设计案例验证函数输出和达成代码覆盖率。</p><p>在白盒测试里，Auto Gen Auto 不是啥稀奇事，XUnit 框架都提供了不少开发 IDE 的 plugin，可以扫描一个 class 的函数，直接产生 test 方法。开发人员只需补充少量代码，test 方法就可以运转起来了。</p><p>与之对应的是黑盒测试，测试案例设计不基于产品代码，而是用户规格说明。比如，用户在订餐系统上完成一个订单，用户该怎么操作，下单成功后应该收到物流单号等等，设计这些测试案例的目的是验证业务能够完成，不需要去看代码。</p><p>今天，我们要关注的是在黑盒测试领域的 Auto Gen Auto，这个更有挑战性，也更有探索价值。因为，作为测试人员花了大量时间来设计黑盒测试案例，而且还要手工维护这些测试案例的变化，这个过程要是都能自动化了，就会省去很大的重复又枯燥的工作量。</p><h3 id="如何实现" tabindex="-1">如何实现 <a class="header-anchor" href="#如何实现" aria-label="Permalink to &quot;如何实现&quot;">​</a></h3><p>怎么做到 Auto Gen Auto 呢？用代码生成代码，前提是测试需求得有一定的规则或模式，然后代码才能解析规则，根据规则生成最终的测试代码。</p><p>这个实现思路，在开发中是很常用的，比如 Maven Archetype 使用模版自动生成项目代码，Soap 使用 WSDL 来生成调用桩等等，原理图如下。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E5%8A%A8%E5%8C%96%E6%B5%8B%E8%AF%95%E9%AB%98%E6%89%8B%E8%AF%BE/images/05/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E5%8A%A8%E5%8C%96%E6%B5%8B%E8%AF%95%E9%AB%98%E6%89%8B%E8%AF%BE/images/05/5.png" alt=""></a></p><p>所以，要做 Auto Gen Auto，我们的目标是先要找出测试需求里的这些规则，并把它们表达出来，放在一个规则文件里。我们看看下面的例子。</p><h2 id="测试等价类的规则" tabindex="-1">测试等价类的规则 <a class="header-anchor" href="#测试等价类的规则" aria-label="Permalink to &quot;测试等价类的规则&quot;">​</a></h2><p>远在天边，近在眼前，我们在测试案例设计中经常用到的等价类和边价值方法，就可以作为Auto Gen Auto 的规则。</p><p>等价类是指某个输入域的子集合，在同一个子集合里的所有元素对于测试的效果都是等价的。</p><p>我们要测试一个订餐系统的用户名，首先要了解用户名上的约束。从长度上来看，假设用户名最大长度是 255 个字节，根据这个约束，至少能产生 2 个测试等价类：有效等价类是小于255 字节的用户名，无效等价类是大于 255 字节的用户名。测试用户注册功能时，就可以用到这 2 个等价类了。</p><p>用同样的思路看用户名的另外一个约束，那就是字符类型的限制，假设用户名只能由英文字母和数字组成，根据这个约束，又可以产生多个等价类，中文字符、ASCII 字符、数字、HighASCII 等等。</p><p>看到没有？其实我们用等价类方法设计测试案例时，遵循的是等价类划分规则，设计出来的测试案例也与等价类一一对应。但手工做这些，工作量会很大，因为整理约束时会有遗漏，改变约束的时候，也容易忘了维护测试案例。</p><p>如果能让测试案例和等价类自动对应，然后依据规则动态产生测试案例，这些问题就会迎刃而解。不过，我们得先把这些约束规则外化表达出来，在这里，我用一个 user-rule.yaml 文件来表达这些规则。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>name: user name rules</span></span>
<span class="line"><span> appliedTestCase: register, login</span></span>
<span class="line"><span> rules:</span></span>
<span class="line"><span>   lengthRule:</span></span>
<span class="line"><span>     express: &lt;=255 chars</span></span>
<span class="line"><span>   characterRule:</span></span>
<span class="line"><span>     express: value&gt;=97 and value&lt;=122</span></span>
<span class="line"><span>     express: value&gt;=48 and value&lt;=57</span></span></code></pre></div><p>为了让这个 YAML 文件能对代码友好，我把 express 表达式部分做了技术处理，ASCII 值从97 到 122 之间是 a～z 的字符，48 到 57 是数字 0～9。</p><p>然后，我们写一段代码，从这个 YAML 文件中直接把规则加载进来，在内存中形成一个分类树。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E5%8A%A8%E5%8C%96%E6%B5%8B%E8%AF%95%E9%AB%98%E6%89%8B%E8%AF%BE/images/05/6.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E5%8A%A8%E5%8C%96%E6%B5%8B%E8%AF%95%E9%AB%98%E6%89%8B%E8%AF%BE/images/05/6.jpeg" alt=""></a></p><p>1 个用户名，有 2 个约束，每种约束都取 1 次不同的等价类，那测试案例的组合总共有 2 * 5=10 个测试案例。</p><p>如果对每一个等价类再加上权值，我们还可以根据权值，过滤掉部分权值偏小的测试案例。基于 YAML 可以生成以下测试案例，从案例名字，你可以看出用户名的取值规则：</p><p>TestUserNameLengthLessThan255</p><p>TestUserNameLengthBigThan255</p><p>TestUserNameAsciiValueLessThan48</p><p>TestUserNameAsciiValueBetween48And57TestUserNameAsciiValueBetween57And97</p><p>TestUserNameAsciiValueBetween97And122</p><p>TestUserNameAsciiValueBigThan122</p><p>好，这里看到成果是很明显的。因为测试案例的生成是自动化的，所以，以后需求变化时，比如允许用户名出现中文，那就在 user-rule.yaml 里增加一条 rule，测试案例也会自动被修改，测试案例维护工作量等于 0。</p><p>到这里，我再画个图总结一下这个方案的实现思路。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E5%8A%A8%E5%8C%96%E6%B5%8B%E8%AF%95%E9%AB%98%E6%89%8B%E8%AF%BE/images/05/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E5%8A%A8%E5%8C%96%E6%B5%8B%E8%AF%95%E9%AB%98%E6%89%8B%E8%AF%BE/images/05/7.png" alt=""></a></p><h2 id="业务的逻辑规则" tabindex="-1">业务的逻辑规则 <a class="header-anchor" href="#业务的逻辑规则" aria-label="Permalink to &quot;业务的逻辑规则&quot;">​</a></h2><p>用等价类的规则表达小试牛刀后，我们尝到了甜头。看来，只要能把规则表达出来，生成测试案例这个工作就可以交给代码去做。我们再找一个更加实用的场景，来看看怎么落地。</p><p>在做 API 测试的时候，restAPI 的接口一般是通过 Open API 规范来描述。在设计阶段，开发先定义要实现的 API 接口，Client 要发送什么样的 Request，Server 要返回什么样的Response。</p><p>比如下面的 user-restapi.yaml 文件，就是遵循 Open API 规范，定义了一个根据 name 查询User 的 RestAPI。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/api/users:</span></span>
<span class="line"><span>   get:</span></span>
<span class="line"><span>     description: 通过name查询用户.</span></span>
<span class="line"><span>     parameters:</span></span>
<span class="line"><span>       - username</span></span>
<span class="line"><span>         type: string</span></span>
<span class="line"><span>         description: 用户name</span></span>
<span class="line"><span>     responses:</span></span>
<span class="line"><span>       &#39;200&#39;:</span></span>
<span class="line"><span>         description: 成功返回符合查询条件的用户列表.</span></span>
<span class="line"><span>         schema:</span></span>
<span class="line"><span>           type: array</span></span>
<span class="line"><span>           items:</span></span>
<span class="line"><span>             $ref: &#39;#/definitions/User&#39;</span></span></code></pre></div><p>这个接口很简单，但它也声明了一个简单的契约，Client 要想查询 User，它需要向 server 发送一个 http get 请求，发送的 url 格式如下：</p><p>http://{host}:{port}/api/users?username=liusheng</p><p>而 server 如果查询到了 User，它应该返回这样一个 http status code 为 200 的 response，内容如下：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">       &quot;items&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">         {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">           &quot;ID&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;123456&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">           &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;liusheng&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">           &quot;age&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">18</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">         }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">         ]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>YAML 文件里定义接口所用到的关键字，像 get、description、parameters 等等，它们都是Open API 里定义好的，含义也是明确的，那么 YAML 表达出来的规则内容也是可以解析出来的。因此，我们同样可以根据规则内容，直接生成测试代码。</p><p>实际上，业界已经有了现成的工具，有 Spring Clond Contract，也有OpenAPI generator。</p><p>我们这就借用这个工具跑一下，把它下载到本地，运行如下命令行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>java -jar openapi-generator-cli.jar generate</span></span>
<span class="line"><span>&gt;   -i user-restapi.yaml \\</span></span>
<span class="line"><span>&gt;   -g java \\</span></span>
<span class="line"><span>&gt;   --library rest-assured</span></span></code></pre></div><p>运行后就会生成一个基于 RestAssure 的测试项目。这个自动生成的项目里包含了 API 测试运行所需要的 Client、Config、Model、API 所有代码。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E5%8A%A8%E5%8C%96%E6%B5%8B%E8%AF%95%E9%AB%98%E6%89%8B%E8%AF%BE/images/05/8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E5%8A%A8%E5%8C%96%E6%B5%8B%E8%AF%95%E9%AB%98%E6%89%8B%E8%AF%BE/images/05/8.png" alt=""></a></p><p>对照上图，UserApi.java 里的 testGetUserByName 函数，就是根据 YAML 文件的 API 定义自动生成的测试代码，可以直接运行。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@ApiOperation(value = &quot;Get user by user name&quot;,</span></span>
<span class="line"><span>       notes = &quot;通过name查询用户&quot;)</span></span>
<span class="line"><span>@ApiResponses(value = {</span></span>
<span class="line"><span>       @ApiResponse(code = 200, message = &quot;成功返回符合查询条件的用户列表&quot;) })</span></span>
<span class="line"><span>public GetUserByNameOper testGetUserByName() {</span></span>
<span class="line"><span>   return new GetUserByNameOper(createReqSpec());</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>是不是很酷？一份契约就这样变成了可执行的测试代码，完全不需要任何开发工作量。</p><p>在解放生产力这件事上，优秀的工程师从不满足。上面只生成了一个测试案例，能不能生成多个测试案例，做更多的测试覆盖，让这个好点子物尽其用呢？</p><p>当然可以，按照等价类规则的思路，多个测试案例来自于多个约束，那我们可以在 YAML 文件中，加入 username 更多的约束描述。在 user-restAPI.yaml 文件里，username 加两行属性，minLength 是 5，maxLength 是 255，代表用户名最小长度是 5 个字符，最大长度是 255个字符。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/api/users:</span></span>
<span class="line"><span>   get:</span></span>
<span class="line"><span>     description: 通过name查询用户</span></span>
<span class="line"><span>     parameters:</span></span>
<span class="line"><span>       - username</span></span>
<span class="line"><span>         type: string</span></span>
<span class="line"><span>         minLength: 5</span></span>
<span class="line"><span>         maxLength: 255</span></span>
<span class="line"><span>         description: 用户name</span></span>
<span class="line"><span>        .............</span></span></code></pre></div><p>现在，我们就可以用等价类规则转变成测试案例的思路，解析 YAML 文件，把testGetUserByName 分裂生成多个测试方法了：</p><p>testGetUserByNameLengthLessThan5</p><p>testGetUserByNameLengthBetween5And255</p><p>testGetUserByNameLengthBigThan255</p><p>OpenAPI generator 这个开源工具就说到这，你可以根据具体需求灵活修改它，加入对 YAML文件任何属性的解析，赋予它测试上的意义，使之成为强大的 Auto Gen Auto 工具，为你所用。</p><p>到这里，我们回顾一下，想要做好 API 测试 0 代码，自动生成的测试案例够多，有 2 个隐含的前提条件要满足：</p><p>1.API 设计先行。在 API设计阶段就要理清接口规则并把它表达出来。</p><ol start="2"><li>在 API 接口的规则文件里，规则描述得越详细，可自动生成的测试案例就会越多。</li></ol><p>在实践中，我看到很多公司忽视了 API 设计先行原则，开发团队写完代码，再生成 YAML 接口文件，然后交给测试人员开发 API 测试代码，这把流程恰好搞颠倒了。本来应该是根据接口设计文档来开发代码，开发和测试都能依据设计并行展开工作，这个做法也会促进团队在设计阶段考虑好设计。</p><p>但是，先写代码再产生接口文档，实际就会默许甚至鼓励开发人员先信马由缰写代码，写出来什么接口都算数。从 API 测试角度来看，测试需求就处在一个不稳定的状态，会带来高昂的自动化测试垂直维护成本。在第二模块里，你也会看到，设计先行对于开发人员内部协作也至关重要。</p><p>另外，有了一份定义完备详细的接口设计文档，Auto Gen Auto 解决方案才可能实现。它不仅能够生成 API test，还可以生成 performance test 等等。</p><p>有兴趣你可以自己研究一下这块的工具（相关工具有兴趣你可以点这里了解），OpenAPI 是其中的一个，我们在后面的课程还会提到 Spring Cloud Contract，也是类似的解决方案。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>今天，我们一起学习了如何通过 Auto Gen Auto 技术，进一步降低我们的开发、维护成本。白盒测试中实现自动生成并不稀奇，所以我们把重心放在了更有挑战的黑盒测试领域。</p><p>想要自动生成测试案例，需要我们先洞察业务场景里的规则，并把它表达出来，形成文档，在团队里达成共识，作为开发和测试的契约。</p><p>我们先从黑盒测试里最熟悉的等价类案例设计方法开始，把用户名的命名规则整理清楚，并且把它表达在一个 YAML 文件里，将这个规则作为我们 Auto Gen Auto 的输入。然后经过加载，解析，最后输出测试案例。在这个过程中，我们关注的是实现思路，没有给出具体的实现方案，有兴趣你可以自己尝试一下。</p><p>在第二个例子里，我们着重看业界经验，以 OpenAPI 为例，它对 RestAPI 接口设计不仅有设计规范，还提供了一套工具集，我们使用了它的 Generator 生产了一个查询 user 的测试案例代码，你能直观感受到它的便利。而且，像 OpenAPI generator 代码都是开源的，你完全可以改造它，做适合自己项目的定制化扩展。</p><p>做 Auto Gen Auto 这样的项目，带来的 ROI 是非常高的，一次性开发工作量，不需要代码维护工作量。重要的话再说一遍：任何提高 ROI 的努力，都是值得去尝试的。</p><h2 id="牛刀小试" tabindex="-1">牛刀小试 <a class="header-anchor" href="#牛刀小试" aria-label="Permalink to &quot;牛刀小试&quot;">​</a></h2><p>访问<a href="https://github.com/OpenAPITools/openapi-generator%EF%BC%8C%E6%8C%89%E7%85%A7%E6%8C%87%E4%BB%A4%EF%BC%8C%E8%BF%90%E8%A1%8C" target="_blank" rel="noreferrer">https://github.com/OpenAPITools/openapi-generator，按照指令，运行</a> generator 命令，在 Python，JavaScript，Java，Go 四种语言里选一种生成代码。</p><p>欢迎你在留言区和我交流互动，也推荐你把这讲内容推荐给身边的测试同学，一起精进技术，提升效率。</p>`,90)])])}const g=e(p,[["render",i]]);export{c as __pageData,g as default};
